def _weight_matches_adapter(key: str, adapter_name: str) -> bool:
    """Return whether a state dict key belongs to the adapter named ``adapter_name``.

    The adapter name is always stored as a complete, dot-delimited segment of the key: either the last segment (for
    parameters/buffers stored in a ``ParameterDict``/``BufferDict``, e.g. ``...ia3_l.default``) or an inner segment (for
    modules stored in a ``ModuleDict``, e.g. ``...lora_A.default.weight``). Matching on the exact segment -- rather than
    a plain substring check -- ensures that, e.g., adapter ``default`` does not pull in the weights of adapters called
    ``default2`` (prefix), ``other_default`` (suffix), ``foodefault_bar`` (infix) or any other name that merely happens
    to contain ``default`` as a substring.
    """
